        new("switch-area", "CREATE TABLE extras FREE (n N(10,0))\nINSERT INTO extras VALUES (77)\nCREATE TABLE src FREE (n N(10,0))\nINSERT INTO src VALUES (1)\nINSERT INTO src VALUES (2)\nGO TOP\nSELECT otherVal() AS val FROM src INTO ARRAY output\nresult=TRANSFORM(output[1,1])+'|'+TRANSFORM(output[2,1])", "FUNCTION otherVal\nLOCAL oldarea, answer\noldarea=SELECT()\nSELECT extras\nanswer=n\nSELECT (oldarea)\nRETURN answer\nENDFUNC\n"),
