        new("sql-binary-sum-b", "CREATE TABLE agg FREE (g I,a N(18,4),b B(4),c Y)\nINSERT INTO agg VALUES (1,1234567890123.5678,999999999999999.5,92233720368.5477)\nINSERT INTO agg VALUES (1,9999999999999.9999,999999999999999.5,-92233720368.5477)\nINSERT INTO agg VALUES (1,10000000000000,999999999999999.5,1234.5678)\nINSERT INTO agg VALUES (1,0.0001,0,0.0001)\nINSERT INTO agg VALUES (1,0.1001,0,0.1)\nSET DECIMALS TO 4\nSELECT SUM(b) AS val FROM agg INTO CURSOR r\nresult=''\nbits=BINTOC(val,'B')\nFOR j=1 TO 8\nresult=result+TRANSFORM(ASC(SUBSTR(bits,j,1)))+','\nENDFOR"),
        new("bits/b", "CREATE TABLE agg FREE (g I,a N(18,4),b B(4),c Y)\nINSERT INTO agg VALUES (1,1234567890123.5678,999999999999999.5,92233720368.5477)\nINSERT INTO agg VALUES (1,9999999999999.9999,999999999999999.5,-92233720368.5477)\nINSERT INTO agg VALUES (1,10000000000000,999999999999999.5,1234.5678)\nINSERT INTO agg VALUES (1,0.0001,0,0.0001)\nINSERT INTO agg VALUES (1,0.1001,0,0.1)\nresult=''\nSCAN\nbits=BINTOC(b,'B')\nFOR j=1 TO 8\nresult=result+TRANSFORM(ASC(SUBSTR(bits,j,1)))+','\nENDFOR\nresult=result+';'\nENDSCAN"),
    ];

    internal static string Observe(Probe probe)
    {
        using var dir = new MicroVfpTestSupport.TempDir("twidthadjudication");
        using var session = new VfpSession();
        session.OpenDirectory(dir.Path);
        using var vfp = new VfpInterpreter(session);
        vfp.Execute(probe.Functions);
        return TransformWidthRound3Tests.Observe(vfp, probe.Body);
    }

    [Fact]
    public void FiniteStoredValues_MatchExpectedVfp()
    {
        var failures = new List<string>();
        foreach (var probe in Probes)
        {
            string actual = Observe(probe);
            if (!ExpectedVfp.TryGetValue(probe.Key, out var expected) || actual != expected)
                failures.Add(probe.Key + ": VFP9=" + expected + "; actual=" + actual);
        }
        Assert.True(failures.Count == 0, string.Join("\n", failures));
    }
}
